class Solution {
public:
    int countSubIslands(vector<vector<int>>& grid1, vector<vector<int>>& grid2) {
        int m = grid1.size();
        int n = grid1[0].size();
        int count = 0;
        int dx[] = {0, 0, 1, -1};
        int dy[] = {1, -1, 0, 0};

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid2[i][j] == 1) {
                    bool isSub = true;
                    queue<pair<int,int>> q;
                    q.push({i, j});
                    grid2[i][j] = 0;
                    while (!q.empty()) {
                        auto [x, y] = q.front();
                        q.pop();
                        if (grid1[x][y] == 0) isSub = false;
                        for (int d = 0; d < 4; d++) {
                            int nx = x + dx[d];
                            int ny = y + dy[d];
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid2[nx][ny] == 1) {
                                grid2[nx][ny] = 0;
                                q.push({nx, ny});
                            }
                        }
                    }
                    if (isSub) count++;
                }
            }
        }
        return count;
    }
};
